CREATE TYPE "user_role" AS ENUM (
  'student',
  'staff',
  'admin'
);

CREATE TYPE "plan_course_status" AS ENUM (
  'passed',
  'failed',
  'planned'
);

CREATE TYPE "review_status" AS ENUM (
  'visible',
  'hidden'
);

CREATE TABLE "users" (
  "user_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "student_id" varchar(20) UNIQUE,
  "email" varchar(255) UNIQUE NOT NULL,
  "first_name" varchar(100) NOT NULL,
  "last_name" varchar(100) NOT NULL,
  "display_name" varchar(100) NOT NULL,
  "role" user_role NOT NULL DEFAULT 'student',
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "users_invitations" (
  "user_invite_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(255) UNIQUE NOT NULL,
  "role" user_role NOT NULL DEFAULT 'staff'
);

CREATE TABLE "courses" (
  "course_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "course_code" varchar(20) UNIQUE NOT NULL,
  "name_th" varchar(255) NOT NULL,
  "name_en" varchar(255) NOT NULL,
  "credits" int NOT NULL,
  "description_th" text,
  "description_en" text,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "curriculum_versions" (
  "curriculum_version_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "version_name" varchar(100) NOT NULL,
  "academic_year" int UNIQUE NOT NULL,
  "total_credits" int NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "categories" (
  "category_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(50) UNIQUE NOT NULL,
  "category_name_th" varchar(100) NOT NULL,
  "category_name_en" varchar(100) NOT NULL,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "curriculum_categories" (
  "curriculum_category_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "curriculum_version_id" int NOT NULL,
  "category_id" int NOT NULL,
  "parent_curriculum_category_id" int,
  "required_credits" int NOT NULL,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "curriculum_category_courses" (
  "curriculum_category_id" int NOT NULL,
  "course_id" int NOT NULL,
  "is_required" boolean NOT NULL DEFAULT false,
  "standard_year" int,
  "standard_semester" int,
  PRIMARY KEY ("curriculum_category_id", "course_id")
);

CREATE TABLE "tracks" (
  "track_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "curriculum_version_id" int NOT NULL,
  "track_name" varchar(100) NOT NULL,
  "description" text,
  "required_credits" int NOT NULL,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "track_courses" (
  "track_id" int NOT NULL,
  "course_id" int NOT NULL,
  "is_required" boolean NOT NULL DEFAULT false,
  "standard_year" int,
  "standard_semester" int,
  PRIMARY KEY ("track_id", "course_id")
);

CREATE TABLE "tags" (
  "tag_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tag_name" varchar(50) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "course_tags" (
  "course_id" int NOT NULL,
  "tag_id" int NOT NULL,
  PRIMARY KEY ("course_id", "tag_id")
);

CREATE TABLE "study_plans" (
  "study_plan_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "curriculum_version_id" int NOT NULL,
  "track_id" int,
  "plan_name" varchar(100) NOT NULL,
  "is_default" boolean NOT NULL DEFAULT false,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE TABLE "study_plan_courses" (
  "study_plan_id" int NOT NULL,
  "course_id" int NOT NULL,
  "study_year" int NOT NULL,
  "study_semester" int NOT NULL,
  "status" plan_course_status NOT NULL DEFAULT 'planned',
  PRIMARY KEY ("study_plan_id", "course_id")
);

CREATE TABLE "reviews" (
  "review_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "course_id" int NOT NULL,
  "overall_rating" int NOT NULL,
  "difficulty_rating" int NOT NULL,
  "workload_rating" int NOT NULL,
  "comment" text,
  "status" review_status NOT NULL DEFAULT 'visible',
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL
);

CREATE UNIQUE INDEX ON "curriculum_categories" ("curriculum_version_id", "category_id");

CREATE UNIQUE INDEX ON "tracks" ("curriculum_version_id", "track_name");

CREATE UNIQUE INDEX ON "reviews" ("user_id", "course_id");

ALTER TABLE "curriculum_categories" ADD FOREIGN KEY ("curriculum_version_id") REFERENCES "curriculum_versions" ("curriculum_version_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "curriculum_categories" ADD FOREIGN KEY ("category_id") REFERENCES "categories" ("category_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "curriculum_categories" ADD FOREIGN KEY ("parent_curriculum_category_id") REFERENCES "curriculum_categories" ("curriculum_category_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "curriculum_category_courses" ADD FOREIGN KEY ("curriculum_category_id") REFERENCES "curriculum_categories" ("curriculum_category_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "curriculum_category_courses" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("course_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tracks" ADD FOREIGN KEY ("curriculum_version_id") REFERENCES "curriculum_versions" ("curriculum_version_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "track_courses" ADD FOREIGN KEY ("track_id") REFERENCES "tracks" ("track_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "track_courses" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("course_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "course_tags" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("course_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "course_tags" ADD FOREIGN KEY ("tag_id") REFERENCES "tags" ("tag_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "study_plans" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "study_plans" ADD FOREIGN KEY ("curriculum_version_id") REFERENCES "curriculum_versions" ("curriculum_version_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "study_plans" ADD FOREIGN KEY ("track_id") REFERENCES "tracks" ("track_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "study_plan_courses" ADD FOREIGN KEY ("study_plan_id") REFERENCES "study_plans" ("study_plan_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "study_plan_courses" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("course_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reviews" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reviews" ADD FOREIGN KEY ("course_id") REFERENCES "courses" ("course_id") DEFERRABLE INITIALLY IMMEDIATE;
